export function boDauTimKiem(v: string | null | undefined): string {
  if (!v) return '';
  let s = '';
  for (const c of v) s += BANG_MOT.get(c) ?? c;
  for (const [nguon, dich] of BANG_NHIEU) s = s.split(nguon).join(dich);
  return s.toLowerCase().replace(/[ \t\n\r\f\v]+/g, ' ').trim();
}
